const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The question asks for 2024, which is in the future. The analysis will be run for the most recent valid year, 2023.
  const aoi = ee.Geometry.Point([-82.502, 35.592]).buffer(50); // Point on Swannanoa River near Asheville, NC
  const date1 = ee.Date('2023-08-30');
  const date2 = ee.Date('2023-10-02');

  // 2. Data Acquisition & Pre-processing
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  // Function to mask clouds, shadows, and non-water pixels using the Scene Classification Layer (SCL)
  // Water pixels are class 6.
  function maskWater(image) {
    const scl = image.select('SCL');
    const waterMask = scl.eq(6); // Select only pixels classified as water
    return image.updateMask(waterMask).copyProperties(image, ['system:time_start']);
  }

  // Get image for the first date
  const col1 = s2Collection.filterBounds(aoi).filterDate(date1, date1.advance(1, 'day'));
  const image1 = col1.map(maskWater).mosaic().select('B4'); // B4 is the Red band

  // Get image for the second date
  const col2 = s2Collection.filterBounds(aoi).filterDate(date2, date2.advance(1, 'day'));
  const image2 = col2.map(maskWater).mosaic().select('B4'); // B4 is the Red band

  // 3. Calculation & Validation
  const scale = 30; // Use a slightly larger scale for robustness
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = image1.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const [val1, count1, val2, count2] = await ee.Promise.all([
    stats1.get('B4_mean'),
    stats1.get('B4_count'),
    stats2.get('B4_mean'),
    stats2.get('B4_count')
  ]).then(results => results.map(r => ee.Number(r).getInfo()));

  console.log(`Note: Using dates from 2023 as 2024 is in the future.`);
  console.log(`August 30, 2023 Red Reflectance: ${val1 ? val1.toFixed(2) : 'N/A'}, Water Pixels: ${count1 || 0}`);
  console.log(`October 2, 2023 Red Reflectance: ${val2 ? val2.toFixed(2) : 'N/A'}, Water Pixels: ${count2 || 0}`);

  // 4. Final Answer Logic
  if (count1 === 0 || count2 === 0) {
    console.log("No valid water pixels found for one or both dates after cloud/scene masking.");
    console.log("C2");
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
      console.log("Calculation failed, resulting in null or NaN values.");
      console.log("C3");
      return;
  }

  // Higher red reflectance suggests "browner" water due to sediment
  if (val2 > val1) {
    console.log("October red reflectance was higher than August, indicating browner water.");
    console.log("A");
  } else {
    console.log("October red reflectance was not higher than August.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
